from depth import *

Lecture('accounting-supply',[
Q('objects','Назначение и объекты учёта','Система снабжения должна связать потребность, закупку, фактическое поступление и доступность материала. Сначала определим, какие объекты она хранит и что означает каждое состояние.',[
 O(1),S('Номенклатура, склад и партия','Номенклатура определяет вид материала; склад — место учёта; партия — конкретное поступление или производственный выпуск. Количество без этих измерений не отвечает на вопрос, можно ли выполнить требование.','Десять единиц на другом складе могут требовать перемещения. Материал нужного вида, но заблокированной партии нельзя считать доступным по тем же правилам, что свободный. Поэтому при сверке сохраняют не только общий итог, но и измерения остатка.'),E('Одинаковое название — разные материалы','Учебные карточки: К-01 — кабель 2×1,5, единица «м»; К-02 — кабель 3×2,5, единица «м». Заявка на 30 м К-02 не покрывается остатком 100 м К-01.','Наименование «кабель» слишком общее. Проверяйте код и характеристики, иначе арифметически достаточный остаток даст физически неподходящий материал. Замена согласуется по предметным правилам, а не выполняется системой по сходству слов.')],Check('Остаток нужного материала есть только на другом складе. Какой вывод корректен?', ['Заявка точно выполнена','Нужно проверить доступность и возможность перемещения к нужной дате','Склад не влияет на учёт'],1,'Остаток по предприятию не равен доступному количеству в нужном месте и сроке.'),'Доступность материала зависит от номенклатуры, места, партии и состояния.'),
Q('documents','Документы и движение материала','Документ связывает реальное событие с изменением учётного состояния. Разберём, почему заказ, приёмка и проведённое движение различаются.',[
 O(2),S('Заказ, поступление и проведение','Заказ поставщику фиксирует согласованное намерение. Приёмка подтверждает фактические количество и состояние. Проведение документа изменяет учётные регистры по принятым правилам. Заказанные 100 единиц ещё не являются наличными 100 единицами.','При недопоставке нельзя проводить заказанное количество как полученное. Сверяют документ поставщика и факт, фиксируют расхождение, затем отражают подтверждённое движение. Это защищает последующее планирование от несуществующего запаса.'),E('Частичная поставка','Учебный заказ — 100 деталей; фактически принято 60, из них 5 помещены в карантин. Наличие принято — 60; свободный пригодный запас от этого поступления — 55; недопоставка по количеству — 40.','Не смешивайте три числа. Карантин не превращает 5 принятых деталей в недопоставленные, но ограничивает выдачу. В отчёте укажите определение каждого показателя.',table(['Показатель','Количество','Основание'],[['Заказано','100','Заказ'],['Принято','60','Факт приёмки'],['Пригодно свободно','55','60 − 5 карантина'],['Недопоставка','40','100 − 60']],'Все количества относятся к одному виду материала и одной единице учёта.'))],Check('Заказано 100, принято 60, в карантине 5. Сколько пригодно для свободной выдачи из поступления?', ['40','55','60','100'],1,'Из 60 принятых 5 заблокированы: свободно 55. Недопоставка 40 отвечает на другой вопрос.'),'Плановый документ, факт поступления и доступный запас имеют разные основания.'),
Q('stock','Остаток, резерв и доступность','Теперь вычислим, какая часть наличия уже обещана другим потребностям. Резерв не является новым физическим расходом, но ограничивает выбор для следующей заявки.',[
 O(3),S('Резерв и двойное обещание','Резерв закрепляет часть запаса за конкретной потребностью. Если наличие 120 и резерв 30, свободно 90. Выдача из резерва одновременно уменьшает наличие и закрывает соответствующий резерв по принятому порядку.','Если после выдачи 20 просто вычесть их из свободных 90 и оставить весь резерв 30, возникнет искажение. Нужны связанные движения: наличие станет 100, резерв 10, свободно останется 90. Это один из способов проверить согласованность состояния.'),E('Изменение резерва без движения товара','Учебное наличие — 80; резерв — 25. Свободно 55. Заказ отменён, резерв 25 снят; физический остаток остаётся 80, свободно становится 80.','Отмена обязательства не является поступлением материала. По журналу должна быть видна причина освобождения резерва. Если оператор оформит приход вместо снятия резерва, учёт покажет 105 единиц и потеряет связь с фактом.')],Check('При наличии 80 и резерве 25 заказ отменён и резерв снят. Какие два утверждения верны?', ['Наличие стало 105','Наличие осталось 80','Свободно стало 80','Нужно списать 25'],[1,2],'Изменилось обязательство, а не физическое количество. Снятие резерва освобождает существующий запас.'),'Резерв изменяет доступность; физическое движение и изменение обязательств отражают раздельно.'),
Q('planning','Расчёт потребности и закупки','Расчёт закупки учитывает не только количество, но и срок. Поступление после нужной даты не покрывает потребность к этой дате.',[
 O(4),S('Горизонт и страховой запас','На выбранную дату сравнивают новую потребность, целевой страховой запас, свободное наличие и подтверждённые своевременные поступления. В простой учебной модели закупка равна положительной части разности этих величин.','Здесь потребность не включает уже зарезервированные заказы; иначе резерв вычитался бы повторно. Формула зависит от определения исходных величин. Перед подстановкой подпишите, какие заказы входят в потребность и какую дату рассматриваем.'),E('Поздняя поставка не закрывает срок','Учебные данные на пятницу: новая потребность 70, свободно 30, страховой запас 10. Подтверждено поступление 20 в четверг и 40 в понедельник. Закупить к пятнице нужно max(0,70+10−30−20)=30.','Если включить понедельник, получится отрицательная потребность, но пятничная функция не выполнится. Отдельно можно рассмотреть ускорение поставки или согласованное изменение срока; это новые условия, а не исправление арифметики.')],Check('К пятнице нужно 70, свободно 30, страховой запас 10; вовремя придёт 20. Сколько нужно дополнительно?', ['0','10','30','40','80'],2,'70+10−30−20=30. Позднее поступление в этот расчёт не входит.'),'Закупку рассчитывают по одинаковой дате и непересекающимся составляющим потребности.'),
Q('integration','Обмен между закупкой, складом и учётом','Одна поставка проходит через несколько подсистем. Для согласованности нужны общие идентификаторы и правила повторного обмена.',[
 S('Сопоставление справочников','Код поставщика, внутренний код и штрихкод могут различаться. Таблица соответствия должна связывать один внешний объект с правильным внутренним товаром и единицей. Новое сопоставление проверяют до массовой загрузки документов.','Поставщик может отправить 10 коробок, а внутренняя единица — штука. При 12 штуках в коробке движение составит 120 штук. Коэффициент должен быть частью проверенного правила, а не устной догадкой оператора.'),S('Повтор сообщения и сверка итогов','Обмен помечают номером или другим устойчивым идентификатором события. Повторное получение уже обработанной накладной должно приводить к прежнему результату либо явному отклонению, а не к второму приходу.','Тест включает один документ, потерю подтверждения и повтор того же сообщения. Затем сверяют число документов и остаток. Транспортное сообщение «доставлено» не заменяет подтверждение предметной обработки.'),E('Дублирование прихода','Начальный остаток 20, накладная Н-8 содержит 15. После первого приёма ожидаем 35. Если повтор Н-8 увеличил итог до 50, защита от дублирования не подтверждена.','Не устраняйте дефект ручной корректировкой итогового остатка без расследования документов: останутся два события. На учебном стенде фиксируют оба идентификатора, правило повтора и повторяют проверку после исправления.',process([('Сообщение Н-8','15 единиц'),('Проверка идентификатора','Н-8 уже проведена?'),('Подтверждение','Прежний результат, без нового движения')],'При повторе одного события количество документов и остаток не должны увеличиваться.'))],Check('Остаток 20, приход Н-8 на 15 передан дважды как одно событие. Какой итог проверять?', ['50 и два прихода','35 и один приход','20 и удалённый журнал'],1,'Повтор одного события не должен удваивать движение. Ожидаем 20+15=35.'),'Обмен проверяют по идентификаторам событий, единицам и сверке итогового состояния.'),
Q('exploitation','Эксплуатация и инвентаризация','Завершим тем, как поддерживать соответствие учёта реальности и как подтверждать восстановление после сбоя.',[
 O(5),S('Инвентаризация и расхождения','Инвентаризация сопоставляет учётное количество с подтверждённым фактом на установленный момент. Перед сравнением согласуют границу: склад, номенклатуру, партии, незавершённые движения и единицы.','Если подсчёт выполнен до выдачи, а отчёт сформирован после неё, расхождение может быть временным. Не создавайте корректировку, пока не восстановлена последовательность событий. Основание исправления и исполнитель сохраняются.'),E('Восстановление после перерыва','Во время перерыва сети приёмка П-42 получила тайм-аут. После восстановления в базе найдена проведённая П-42 на 10 единиц. Повторный приход с новым номером создавать нельзя без проверки фактического события.','Сначала сопоставьте номер, время, строки и остаток. Затем восстановите подтверждение оператору и сверку обмена. Отсутствие ответа на клиенте не доказывает отсутствие записи.')],Check('Клиент получил тайм-аут, но П-42 уже проведена. Первое действие после восстановления?', ['Повторить приход новым документом','Проверить П-42 и фактический итог по её идентификатору','Удалить все журналы'],1,'Нужно установить судьбу исходной операции, чтобы не создать дубликат.'),'Эксплуатация поддерживает согласованность документов, факта, резервов и обмена.')
],[('Почему заказ поставщику нельзя считать наличным остатком?','Заказ описывает намерение, а наличие подтверждает фактическая приёмка и учётное движение.'),('Чем снятие резерва отличается от прихода?','Снятие освобождает существующий запас; приход увеличивает подтверждённое наличие.'),('Какие данные нужны перед исправлением инвентаризационного расхождения?','Единый момент и граница учёта, единицы, фактический подсчёт и последовательность движений.')],H('К среде новая потребность 90 шт., наличие 100, из него 40 зарезервировано под другие заказы; страховой запас 15. Во вторник придёт 20, в четверг — 30.','Определите свободное наличие, учитываемое поступление и дополнительную закупку к среде.','Запишите формулу, промежуточные величины и объясните исключение четверга.','Свободно 100−40=60; вовремя 20; закупка max(0,90+15−60−20)=25 шт.'))

Lecture('production-quality',[
Q('levels','Планирование и исполнение производства','Различим решение о выпуске, задание на операцию и подтверждённое выполнение. Эти сведения связаны, но не взаимозаменяемы.',[
 O(1),S('ERP, MES и управление оборудованием','В учебном разделении ERP согласует ресурсы и заказы, MES поддерживает исполнение операций, системы управления оборудованием работают с технологическими сигналами. Реальное распределение зависит от конкретного комплекса.','Одна и та же программа может объединять несколько ролей. При эксплуатации важнее показать, откуда пришло задание, где подтверждается факт и какой уровень разрешает действие. Производственный отчёт не является командой безопасного управления станком.'),E('План не равен выпуску','Учебный заказ — 100 изделий. На участке подтверждено 80 обработанных; из них 6 признаны несоответствующими. План 100, фактическая обработка 80, годный выпуск 74 — три разных показателя.','Вычитание 6 из плана дало бы 94 и скрыло невыполненные 20. Показатели подписывают по источнику: план, событие выполнения и решение контроля.',table(['Величина','Число','Подтверждение'],[['План','100','Заказ'],['Обработано','80','Факт операции'],['Годно','74','80 − 6 несоответствий']],'Для сравнения сохраняются одна партия и один момент отчёта.'))],Check('План 100, обработано 80, несоответствующих 6. Каков подтверждённый годный выпуск?', ['74','80','94','100'],0,'Годность относится к обработанным 80: 80−6=74.'),'План, исполнение и годность подтверждают разные события.'),
Q('routing','Маршрут, операция и ресурсы','Производственная система описывает не только готовое изделие, но и последовательность его получения. Свяжем материал, операцию, оборудование и исполнителя.',[
 S('Спецификация и маршрут','Спецификация задаёт состав материала или изделия; маршрут — операции и их порядок. Для выполнения нужны также количество, единицы, доступный ресурс и действующая редакция документов.','Изменение материала и изменение порядка обработки — разные изменения. Если применена новая спецификация, в факте партии нужно сохранить её редакцию. Иначе позднее нельзя объяснить, по каким правилам изготовлен конкретный выпуск.'),S('Состояния производственного задания','Задание может быть запланировано, разрешено, начато, приостановлено и завершено. Переход подтверждается событием и полномочием. Приостановка не означает выпуск, а завершение операции не всегда завершает весь маршрут.','Для двух операций А и Б факт А разрешает следующий шаг только при выполнении условий маршрута. Недостающий контроль может блокировать Б. Это связь состояний и правил, а не просто последовательность экранов.'),E('Две операции и контрольный переход','Учебный маршрут: обработка → измерение → упаковка. После обработки 20 деталей измерение выявило 2 несоответствия. В упаковку разрешено передать 18, а не все 20.','Покажите точку решения. Две детали остаются в отдельном состоянии до решения о доработке или браке. Если операция упаковки получает только число 20 без статуса, система теряет управляемость качества.',process([('Обработка','20 деталей'),('Контроль','18 годных; 2 заблокированы'),('Упаковка','18 разрешённых')],'Переход зависит от результата контроля, а не только от завершения предыдущей операции.'))],Check('Обработка завершена, обязательное измерение ещё нет. Что следует из этого?', ['Вся партия автоматически годна','Нужно получить решение контроля перед разрешённым следующим этапом','Измерение можно заменить названием файла'],1,'Завершение операции и подтверждение качества — разные условия маршрута.'),'Маршрут связывает операции с условиями переходов и актуальными исходными документами.'),
Q('trace','Партии и прослеживаемость','Чтобы локализовать последствие дефекта, нужно восстановить связи конкретного выпуска. Общего отчёта по месяцу для этого недостаточно.',[
 O(2),S('Идентификаторы и фактические связи','Для партии сохраняют использованные партии материалов, операцию, оборудование, время, исполнителя и результаты контроля. Связь должна отражать факт: один заказ может выпускаться несколькими партиями на разных ресурсах.','При обнаружении дефекта материала М-7 ищут именно выпуски, которые его использовали. Без связи придётся расширять проверку на весь период. Чем точнее факт, тем уже обоснованный контур проверки; отсутствие записи нельзя заменить догадкой.'),E('Поиск затронутого выпуска','Учебные связи: партия P1 использовала М7; P2 — М8; P3 — М7 и М9. При подтверждённом дефекте М7 первично проверяют P1 и P3. Принадлежность P2 тому же дню ещё не делает её затронутой.','Вывод ограничен полнотой записей. Если использование материала в P2 не зарегистрировано, нельзя объявлять её безопасной только по пустой связи. Сначала проверяют достоверность производственного учёта.')],Check('P1 использовала М7, P2 — М8, P3 — М7 и М9. Какие две партии связаны с М7?', ['P1','P2','P3','Ни одна'],[0,2],'Прослеживаемость строится по фактическим связям партий, а не по совпадению даты.'),'Прослеживаемость связывает конкретный выпуск с материалом, операциями и контролем.'),
Q('measurement','Измерение и достоверность результата','Контроль качества опирается на измеренную величину и применимое правило. Различим показание прибора, решение и пригодность средства измерения.',[
 O(3),S('Единица, допуск и средство измерения','Для результата сохраняют величину, единицу, точку и условия измерения, средство измерения и применимое требование. Значение 10,05 без единицы и допустимого диапазона не позволяет решить вопрос годности.','Сравнение проводят в одинаковых единицах. Состояние и пригодность прибора проверяют по принятому порядку. В этой учебной модели неопределённость измерения не рассчитываем: если она влияет на пограничное решение, нужны дополнительные правила, а не произвольное округление.'),E('Граница допуска','Учебное правило: размер должен быть от 9,90 до 10,10 мм включительно. 10,10 соответствует числовому правилу; 10,11 — превышает верхнюю границу. Округление 10,11 до 10,1 до сравнения скрыло бы несоответствие.','Сначала сравнивают исходное значение с правилом, затем оформляют результат с согласованной точностью. Если реальное правило учитывает неопределённость, его необходимо задать отдельно; из этого простого примера оно не выводится.')],Check('При диапазоне [9,90; 10,10] мм и заданном включении границ какое значение не соответствует?', ['9,90','10,00','10,10','10,11'],3,'10,11 больше 10,10. Предварительное округление может ошибочно скрыть превышение.'),'Решение контроля требует значения, единицы, правила и пригодных исходных условий.'),
Q('nonconformity','Несоответствие и решение по партии','Зафиксированное отклонение ещё не определяет судьбу всей партии. Нужен принятый порядок блокировки, оценки и последующего решения.',[
 O(4),S('Статус и изоляция несоответствующего','Несоответствие связывают с конкретным объектом и требованием. До разрешённого решения объект блокируют от обычного выпуска. Доработка, повторный контроль и списание имеют разные основания и состояния.','Физическая бирка и информационный статус должны соответствовать друг другу. Если в программе объект заблокирован, но на участке его можно без проверки упаковать, граница контроля неполна. После доработки сохраняют связь с исходным несоответствием.'),E('Среднее не заменяет проверку каждого изделия','Учебное требование относится к каждому размеру: 9,90–10,10 мм. Измерены 9,96; 10,00; 10,14. Среднее около 10,033 допустимо по числу, но третье изделие нарушает правило.','Чтобы признать всю группу годной, нужно выполнить правило для каждого проверяемого объекта либо явно заданный план выборочного контроля. Нельзя молча заменить индивидуальное требование условием по среднему.')],Check('Среднее трёх размеров допустимо, один размер превышает индивидуальный предел. Что подтверждено?', ['Все изделия годны','Есть индивидуальное несоответствие; среднее его не отменяет','Нужно удалить наибольшее измерение'],1,'Правило задано для каждого изделия. Среднее отвечает на другой вопрос.'),'Несоответствие сохраняют как проверяемый объект с отдельным решением и повторным контролем.'),
Q('service','Особенности эксплуатации','Производственная система работает рядом с физическим процессом. Восстановление её данных и сервисов требует согласованности с реальными заданиями и состояниями оборудования.',[
 O(5),S('Время, обмен и незавершённые операции','При задержке сообщений различают момент события и момент регистрации. После перерыва нужно сверить задания, фактические операции и поступившие результаты. Повтор события с тем же идентификатором не должен давать второй выпуск.','Не подтверждайте автоматически все накопленные сообщения. Проверьте порядок, номера партий и состояния. Сервис может восстановиться быстрее, чем согласованность данных; поэтому возврат к работе включает сверку незавершённых операций.'),E('Повтор производственного отчёта','Учебное событие F-9 фиксирует выпуск 18 изделий. После потери подтверждения оно отправлено повторно. Правильная сверка показывает одно F-9 и выпуск 18, а не 36.','Для проверки нужны идентификатор события и исходный выпуск. Простое сравнение сумм за день может не найти дубликат, если параллельно было другое исправление. Сначала исследуют конкретную последовательность.')],Check('После восстановления сети пришёл повтор F-9 на 18 изделий. Что нужно проверить?', ['Выпуск должен стать 36','Существует одно событие F-9 и один соответствующий выпуск','Все незавершённые партии можно закрыть'],1,'Повтор передачи одного факта не является новым физическим выпуском.'),'Эксплуатация согласует состояние ИС с фактическими партиями и незавершёнными операциями.')
],[('Чем производственное задание отличается от подтверждённого выпуска?','Задание разрешает и планирует работу; выпуск подтверждает фактический результат.'),('Почему средний размер не доказывает годность каждого изделия?','Индивидуальное требование нужно проверить для каждого объекта; среднее может скрыть превышение.'),('Что проверяют после перерыва обмена с участком?','Судьбу конкретных событий, идентификаторы, незавершённые операции и согласованность итогового выпуска.')],H('Для партии из 4 деталей измерены размеры 9,95; 10,10; 10,12; 9,98 мм. Учебный допуск — [9,90; 10,10] мм для каждой детали, границы включены.','Сначала примените правило к каждому значению, затем предложите информационное состояние до решения ответственного.','Представьте протокол четырёх измерений, число соответствующих деталей и порядок повторного контроля.','Соответствуют 3 из 4; 10,12 нарушает верхний предел. Несоответствующий объект блокируется; среднее не отменяет дефект.'))

Lecture('reference-library',[
Q('records','Библиографическая запись и экземпляр','Начнём с различия между описанием издания и конкретным объектом фонда. Иначе поиск книги будет ошибочно восприниматься как разрешение её выдать.',[
 O(1),S('Описание, издание и физическая единица','Библиографическая запись содержит сведения об издании: название, авторство, выходные данные и идентификаторы. Экземпляр имеет собственный инвентарный номер, местонахождение и состояние. Несколько экземпляров могут ссылаться на одно описание.','Исправление названия в общей записи отражается на поиске всех связанных экземпляров, а возврат одного экземпляра меняет его состояние. Поэтому при обслуживании сначала определяют уровень изменения.'),E('Одно описание, три экземпляра','Учебная запись B-11 связана с E-111, E-112 и E-113. E-111 выдан, E-112 доступен для выдачи, E-113 используется только в читальном зале. Найдена одна запись, но доступен для обычной выдачи один экземпляр.','Нельзя считать число результатов поиска числом доступных книг. Отдельно проверяют ограничения читателя и фонда. Даже E-112 может быть зарезервирован другим читателем по принятому порядку.',table(['Объект','Состояние','Обычная выдача'],[['E-111','На руках','Нет'],['E-112','Свободен','При выполнении правил'],['E-113','Читальный зал','По отдельным правилам']],'Все экземпляры относятся к B-11; библиографическое описание не является состоянием выдачи.'))],Check('Поиск нашёл B-11 с тремя экземплярами. Что можно утверждать?', ['Все три можно выдать','Найдено описание; доступность каждого экземпляра проверяется отдельно','Есть три разных издания'],1,'Нужно различать описание и экземпляры с их статусами.'),'Описание отвечает на вопрос «что это за издание», экземпляр — «какая конкретно единица и где она». '),
Q('search','Поиск и индексирование','Поиск использует подготовленные признаки записи. Корректное хранение карточки и её присутствие в поисковой выдаче — разные проверки.',[
 S('Поля поиска и нормализация','Запрос может искать по названию, автору, теме или идентификатору. Поисковый индекс подготавливает эти признаки для быстрого отбора. Настройки нормализации и выбранное поле влияют на совпадение.','Отсутствие результата по свободному запросу не доказывает отсутствия записи. Проверьте точный идентификатор и само описание. Затем исследуйте индекс и правила запроса, сохраняя первоначальные данные.'),O(4),E('Запись есть, индекс устарел','Учебное наблюдение: B-10 открывается по номеру, новое название сохранено; поиск по новому названию результата не даёт, по старому — даёт. Это основания проверить актуальность индекса.','Не создавайте дубликат B-10, чтобы «появилось в поиске»: экземпляры останутся связаны с прежней записью. Выполняют разрешённое обновление индекса и проверяют обе формы поиска. Конкретная команда зависит от установленной системы.')],Check('B-10 открывается по ID, поиск по новому названию не работает. Какое действие обосновано?', ['Создать вторую карточку с тем же изданием','Проверить индекс и настройки поля поиска','Удалить экземпляры'],1,'Есть подтверждённая запись и расхождение поискового представления; дублирование создаст новый дефект.'),'Диагностика поиска различает исходную запись, индекс, запрос и правила совпадения.'),
Q('circulation','Выдача, возврат и резервирование','Выдача связывает читателя, экземпляр и срок. Проследим, как изменяется конкретный объект и какие условия проверяются перед действием.',[
 O(2),S('Проверки перед выдачей','Определяют читателя, конкретный экземпляр, допустимость его использования и применимые ограничения. После выдачи фиксируются связанная запись и срок; при возврате закрывается та же операция и пересматривается доступность.','Сканирование сначала выбирает объект, но не обязано обходить правила. Отказ в выдаче может быть штатным результатом ограничения, а не поломкой программы. В журнале важно различать запрещённое действие и техническую ошибку.'),E('Возврат не всегда делает экземпляр свободным','Учебный E-101 возвращён после выдачи, но на него есть действующий резерв другого читателя. Состояние «на руках» закончено; немедленная свободная выдача любому читателю может быть запрещена.','Изменилось физическое наличие, но осталось обязательство. Сравните этот случай с отсутствием резерва: тогда после предусмотренной обработки экземпляр может стать доступным. Ответ зависит от правил обращения фонда.')],Check('Экземпляр возвращён и зарезервирован другим читателем. Что проверять перед новой выдачей?', ['Только цвет обложки','Действующий резерв и правила его обслуживания','Только число страниц'],1,'Возврат завершает прежнюю выдачу, но не отменяет действующих обязательств.'),'Выдача и возврат изменяют состояние экземпляра в рамках правил и резервов.'),
Q('access','Доступ и особенности ресурсов','Различим возможность найти описание, прочитать ресурс и выполнить служебное действие. Для электронного и физического фонда ограничения могут иметь разные основания.',[
 O(3),S('Читательский и служебный интерфейсы','Читатель ищет и запрашивает доступ; сотрудник описывает фонд, регистрирует экземпляры и выполняет обслуживание. Эти действия разделяются правами. Публичное описание не означает право изменять сведения или получать любой полный текст.','Для электронного ресурса дополнительно проверяют условия доступа, учётную запись и доступность внешнего сервиса. Ошибка авторизации и отсутствие файла имеют разные причины. Не предлагается обход ограничений путём копирования чужой сессии.'),E('Доступ к карточке и полному тексту','Учебная карточка электронного издания открывается всем; полный текст доступен только авторизованным пользователям организации. У гостя видна карточка, переход к тексту требует входа.','Это может быть корректным поведением, если соответствует установленным условиям. Сначала проверьте роль пользователя и описание правил. Недоступность всем разрешённым пользователям уже требует отдельной диагностики сервиса.')],Check('Гость видит карточку, полный текст требует входа по правилам ресурса. Что подтверждено?', ['Система обязательно неисправна','Описание доступно; доступ к полному тексту проверяется по отдельным условиям','Нужно выдать гостю служебную роль'],1,'Поиск описания и право чтения полного текста являются разными функциями.'),'Доступ к описанию, содержимому и служебным операциям разграничивают.'),
Q('maintenance','Эксплуатация и целостность фонда','Устойчивость библиотечной ИС зависит от связей записей, актуальности статусов и восстановимости данных. Проверка одной страницы не закрывает эти зависимости.',[
 O(5),S('Инвентаризация и исправление связей','Сверка фонда сравнивает конкретные экземпляры с учётом, местом и состоянием на выбранный момент. Дубликат штрихкода, потерянная связь с описанием и ошибочный статус требуют разных исправлений.','Перед изменением сохраняют идентификаторы и основание. Нельзя удалять общее описание только потому, что один экземпляр утрачен: другие экземпляры могут продолжать использовать запись. Сначала устанавливают область воздействия.'),E('Восстановление и контроль связности','После учебного восстановления базы проверяют B-10, все её экземпляры, открытую выдачу E-101 и соответствующего читателя. Открытие каталога без этих связей не подтверждает восстановление обращения фонда.','Отдельно выполняют разрешённую выдачу и возврат тестового экземпляра. Индекс можно восстановить из записей, но это не заменяет сохранение самих записей и истории операций.')],Check('Утрачен один из трёх экземпляров. Какое действие требует обоснования вместо автоматического удаления?', ['Изменить статус конкретного экземпляра','Удалить общую запись издания вместе с оставшимися экземплярами','Сохранить идентификатор утраченного экземпляра'],1,'Удаление общего описания затрагивает другие единицы и связи; утрата одного экземпляра не является достаточным основанием.'),'Эксплуатация поддерживает связи описаний, экземпляров, читателей, выдач и поискового представления.')
],[('Почему одна найденная карточка не задаёт число доступных книг?','Она описывает издание; доступность определяется по каждому экземпляру и ограничениям.'),('Когда отказ в выдаче является штатным результатом?','Когда действие нарушает действующее правило или резерв; техническое исполнение отказа при этом может быть исправным.'),('Что проверяют после восстановления библиотечной базы?','Сами описания, экземпляры, действующие выдачи и читателей, затем сквозные операции и поиск.')],H('У записи B-20 четыре экземпляра: один выдан, один в ремонте, один свободен для обычной выдачи, один доступен только в читальном зале. Действующих резервов нет.','Определите число экземпляров для обычной выдачи и подготовьте проверку возврата выданного экземпляра.','Сдайте таблицу состояний и ожидаемое изменение доступности при отсутствии новых ограничений.','До возврата доступен 1; после корректного возврата и обычной обработки станет 2, если правила и состояние возвращённого экземпляра допускают выдачу.'))
